"""netinventory.py: a small, reusable inventory module."""


class Device:
    """A managed network device."""

    def __init__(self, hostname, mgmt_ip, platform="iosxe"):
        self.hostname = hostname
        self.mgmt_ip = mgmt_ip
        self.platform = platform
        self.interfaces = []

    def add_interface(self, name, enabled=True):
        self.interfaces.append({"name": name, "enabled": enabled})

    def __repr__(self):
        return f"{type(self).__name__}({self.hostname!r}, {self.mgmt_ip!r})"


class Switch(Device):
    """A switch is a Device that also has VLANs."""

    def __init__(self, hostname, mgmt_ip, vlans=None):
        super().__init__(hostname, mgmt_ip, platform="iosxe")
        self.vlans = vlans or []


def find_by_platform(devices, platform):
    """Return the devices that run the given platform."""
    return [d for d in devices if d.platform == platform]


if __name__ == "__main__":
    inventory = [
        Device("edge-r1", "192.0.2.1"),
        Switch("access-sw1", "192.0.2.11", vlans=[10, 20]),
        Device("dc-n9k1", "192.0.2.21", platform="nxos"),
    ]
    print(find_by_platform(inventory, "iosxe"))

class LinkMonitor:
    """Subject: keeps a list of observers and notifies them of changes."""

    def __init__(self):
        self._observers = []

    def subscribe(self, callback):
        self._observers.append(callback)

    def link_changed(self, device, interface, state):
        for notify in self._observers:
            notify(device, interface, state)


def write_log(device, interface, state):
    print(f"LOG   {device} {interface} is {state}")


def page_on_call(device, interface, state):
    if state == "down":
        print(f"PAGE  {device} {interface} went down")


monitor = LinkMonitor()
monitor.subscribe(write_log)
monitor.subscribe(page_on_call)
monitor.link_changed("edge-r1", "GigabitEthernet2", "down")
monitor.link_changed("edge-r1", "GigabitEthernet2", "up")

